const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof $json.tender_id !== 'string' || !uuid.test($json.tender_id) || typeof $json.org_id !== 'string' || !uuid.test($json.org_id)) {
  throw new Error('INVALID_TENANT_CONTEXT');
}
return [{ json: $json }];

// Build the complete selected source before applying the provider input bound.
const tender = $('load-tender').first().json;
const pdfTexts = tender.pdf_texts_extracted;
const sourceCharLimit = 12000;
let sourceText = '';
let actualSourceText = '';

if (pdfTexts) {
  if (Array.isArray(pdfTexts)) {
    actualSourceText = pdfTexts.map((text) => String(text || '').trim()).join('');
    sourceText = pdfTexts
      .map((t, i) => '=== Dokument ' + (i + 1) + ' ===\n' + (t || ''))
      .join('\n\n');
  } else if (typeof pdfTexts === 'object') {
    actualSourceText = Object.values(pdfTexts).map((text) => String(text || '').trim()).join('');
    sourceText = Object.entries(pdfTexts)
      .map(function(entry) { return '=== ' + entry[0] + ' ===\n' + (entry[1] || ''); })
      .join('\n\n');
  } else {
    actualSourceText = String(pdfTexts);
    sourceText = actualSourceText;
  }
}

if (actualSourceText.trim().length < 50 && tender.pdf_text) {
  actualSourceText = String(tender.pdf_text);
  sourceText = actualSourceText;
}
const sourceInsufficient = !actualSourceText || actualSourceText.trim().length < 50;
let extractionText = sourceText.slice(0, sourceCharLimit);

// Last resort: seed with structural info from the archive so the AI has some context.
if (sourceInsufficient) {
  const lines = [];
  if (tender.title && tender.title !== 'Leistungsverzeichnis') {
    lines.push('Projekttitel: ' + tender.title);
  }
  const gaebFiles = tender.raw_gaeb_json || [];
  for (const g of gaebFiles) {
    if (g._error && typeof g._error === 'string') {
      const otherMatch = g._error.match(/Other: \[([^\]]+)\]/);
      if (otherMatch) {
        const paths = otherMatch[1].split(', ');
        const folders = new Set();
        for (const p of paths) {
          const parts = p.split('/');
          if (parts.length >= 3) folders.add(parts[parts.length - 2]);
        }
        if (folders.size > 0) lines.push('Teilleistungen: ' + Array.from(folders).join(', '));
      }
      const pdfMatch = g._error.match(/PDFs: \[([^\]]+)\]/);
      if (pdfMatch) {
        const lvPdfs = pdfMatch[1].split(', ')
          .map(function(p) { return p.split('/').pop(); })
          .filter(function(n) { return /lv|leistung|ausschreib|verzeichnis/i.test(n); })
          .slice(0, 5);
        if (lvPdfs.length > 0) lines.push('Dokumente: ' + lvPdfs.join(', '));
      }
    }
  }
  if (lines.length > 0) {
    sourceText = lines.join('\n');
    extractionText = sourceText.slice(0, sourceCharLimit);
  }
}

const requirements_coverage = {
  source_insufficient: sourceInsufficient,
  source_truncated: sourceText.length > sourceCharLimit,
  source_char_count: sourceText.length,
  extracted_char_count: extractionText.length,
  source_char_limit: sourceCharLimit
};
return [{ json: Object.assign({}, tender, { extraction_text: extractionText, requirements_coverage }) }];

const categories = ['Zertifizierung', 'Versicherung', 'Referenz', 'Personal', 'Ausrüstung', 'Sicherheit', 'Finanziell', 'Tariflich', 'Erlaubnis', 'Sonstiges'];
const requirementLimit = 25;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isBoundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const parseIfString = (value) => typeof value === 'string' ? JSON.parse(value) : value;

let requirements;
try {
  const content = $json.choices?.[0]?.message?.content;
  const parsed = typeof content === 'string'
    ? JSON.parse(content.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim())
    : content;
  if (Array.isArray(parsed)) {
    requirements = parsed;
  } else if (isObject(parsed)) {
    const wrapped = ['requirements', 'items']
      .filter((key) => Object.prototype.hasOwnProperty.call(parsed, key));
    if (wrapped.length !== 1) throw new Error('invalid response');
    requirements = parseIfString(parsed[wrapped[0]]);
  }
  if (!Array.isArray(requirements) || requirements.length > requirementLimit) {
    throw new Error('invalid response');
  }

  const ids = new Set();
  requirements = requirements.map((requirement) => {
    if (!isObject(requirement)) throw new Error('invalid response');
    const sourceFragments = typeof requirement.source_fragments === 'string'
      ? [requirement.source_fragments]
      : parseIfString(requirement.source_fragments);
    if (
      !isBoundedString(requirement.id, 100) ||
      !categories.includes(requirement.category) ||
      !isBoundedString(requirement.title, 200) ||
      !isBoundedString(requirement.description, 4000) ||
      typeof requirement.is_critical !== 'boolean' ||
      typeof requirement.is_implicit !== 'boolean' ||
      !Array.isArray(sourceFragments) ||
      sourceFragments.length > 20 ||
      !sourceFragments.every((fragment) => isBoundedString(fragment, 2000)) ||
      ids.has(requirement.id)
    ) throw new Error('invalid response');
    ids.add(requirement.id);
    return {
      id: requirement.id,
      category: requirement.category,
      title: requirement.title,
      description: requirement.description,
      is_critical: requirement.is_critical,
      is_implicit: requirement.is_implicit,
      source_fragments: sourceFragments,
    };
  });
} catch {
  console.error('LLM_RESPONSE_INVALID_JSON');
  throw new Error('LLM_RESPONSE_INVALID_JSON');
}
const sourceCoverage = $('prepare-extraction-text').first().json.requirements_coverage;
const requirements_coverage = {
  ...sourceCoverage,
  requirement_count: requirements.length,
  requirement_limit: requirementLimit,
  requirement_limit_reached: requirements.length === requirementLimit
};
return [{ json: { requirements, requirements_coverage } }];

const tender = $('load-tender').first().json;
const positions = Array.isArray(tender.gaeb_positions) ? tender.gaeb_positions : [];
const chunkSize = 120;
const maxChunks = 10;
if (positions.length > chunkSize * maxChunks) throw new Error('WORKLOAD_POSITION_LIMIT_EXCEEDED');
const chunkCount = Math.max(1, Math.ceil(positions.length / chunkSize));
const classificationKey = (index) => 'POS-' + String(index + 1).padStart(3, '0');
const systemPrompt = 'Du bist ein Experte für deutsche öffentliche Ausschreibungen (GAEB/VOB) und Bauwirtschaft. Klassifiziere jede Position als eigen, fremd, liefer oder gemischt. Eigen bedeutet typische Kernleistung eines generischen Bauunternehmens; fremd bedeutet spezialisiertes anderes Gewerk oder Fachunternehmen; liefer ist reine Lieferung ohne Einbau; gemischt kombiniert Lieferung und Einbau. Baustelleneinrichtung und Verkehrssicherung sind typischerweise eigen; pauschale bzw. psch-ähnliche Positionen können auf Fremdleistungspakete hinweisen, sind aber im Kontext zu beurteilen. Ordne außerdem jede Position genau einmal einer semantischen Arbeitsgruppe zu. Gruppiere nach fachlicher Bedeutung und zusammenhängendem Arbeitspaket, nie allein nach gleicher Einheit. Halte abweichende Dimensionen, Materialien, Verfahren und entscheidende Merkmale getrennt. Bei fachlicher Unklarheit verwende kind ambiguous statt zu raten. Gib keine Mengen-Summen aus. Antworte nur als JSON-Objekt: {"classifications":[{"id":"POS-001","type":"eigen|fremd|liefer|gemischt","reason":"Begründung"}],"groups":[{"id":"GROUP-001","label":"Arbeitspaket","kind":"semantic|ambiguous","position_ids":["POS-001"],"distinguishing_attributes":["Merkmal"],"confidence":0.0,"rationale":"Begründung"}]}';
return Array.from({ length: chunkCount }, function(_, chunkIndex) {
  const start = chunkIndex * chunkSize;
  const chunkPositions = positions.slice(start, start + chunkSize).map(function(position, offset) {
    return {
      id: classificationKey(start + offset),
      unit: position.unit,
      short_text: position.short_text,
      category: (position.category_path || []).join(' > ')
    };
  });
  return { json: {
    chunk_index: chunkIndex,
    chunk_count: chunkCount,
    positions: chunkPositions,
    request_body: {
      model: 'gemini-3.5-flash-lite',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: 'Gewerk: ' + (tender.trade_category || 'unbekannt') + '\n\nPositionen:\n' + JSON.stringify(chunkPositions) }
      ],
      temperature: 0,
      response_format: { type: 'json_object' }
    }
  } };
});

