const chunks = $('prepare-workload-chunks').all();
const responses = $input.all();
if (responses.length !== chunks.length || responses.length < 1 || responses.length > 10) throw new Error('LLM_RESPONSE_INVALID_JSON');
const parseIfString = (value) => typeof value === 'string' ? JSON.parse(value) : value;
const combined = { classifications: [], groups: [] };
for (let index = 0; index < responses.length; index++) {
  try {
    const content = responses[index].json.choices?.[0]?.message?.content;
    const decoded = typeof content === 'string'
      ? JSON.parse(content.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim())
      : content;
    const parsed = parseIfString(decoded);
    const rawClassifications = Array.isArray(parsed)
      ? parsed
      : (parsed?.classifications ?? parsed?.positions ?? parsed?.items);
    const classifications = parseIfString(rawClassifications);
    if (!Array.isArray(classifications)) throw new Error('invalid classifications');
    combined.classifications.push(...classifications);
    if (parsed && !Array.isArray(parsed) && parsed.groups != null) {
      const groups = parseIfString(parsed.groups);
      if (!Array.isArray(groups)) throw new Error('invalid groups');
      combined.groups.push(...groups.map(function(group) {
        return { ...group, id: 'CHUNK-' + String(index + 1).padStart(2, '0') + '-' + group.id };
      }));
    }
  } catch {
    throw new Error('LLM_RESPONSE_INVALID_JSON');
  }
}
return [{ json: { choices: [{ message: { content: JSON.stringify(combined) } }] } }];

const tender = $('load-tender').first().json;
const allPositions = Array.isArray(tender.gaeb_positions) ? tender.gaeb_positions : [];
// Early exit: no GAEB positions — PDF-only tender, skip classification
if (!allPositions.length) {
  return [{ json: { ...$json, value_breakdown: null } }];
}
// Validate the complete position set assembled from bounded model chunks.
const positions = allPositions;
const classificationKey = (index) => 'POS-' + String(index + 1).padStart(3, '0');
const wrapperKeys = ['positions', 'items', 'classifications'];
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isBoundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const parseIfString = (value) => typeof value === 'string' ? JSON.parse(value) : value;

let classified;
let rawGroups;
try {
  const rawContent = $json.choices?.[0]?.message?.content;
  const parsed = typeof rawContent === 'string'
    ? JSON.parse(rawContent.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim())
    : rawContent;
  if (Array.isArray(parsed)) {
    classified = parsed;
  } else if (isObject(parsed)) {
    const presentWrapperKeys = wrapperKeys
      .filter((key) => Object.prototype.hasOwnProperty.call(parsed, key));
    if (presentWrapperKeys.length !== 1) throw new Error('invalid response');
    classified = parseIfString(parsed[presentWrapperKeys[0]]);
    rawGroups = parsed.groups;
  }

  if (!Array.isArray(classified) || classified.length !== positions.length || classified.length > 1200) {
    throw new Error('invalid response');
  }
  const knownIds = new Set(positions.map((_, index) => classificationKey(index)));
  const classifiedIds = new Set();
  classified = classified.map((classification) => {
    if (
      !isObject(classification) ||
      !isBoundedString(classification.id, 100) ||
      !knownIds.has(classification.id) ||
      classifiedIds.has(classification.id) ||
      !['eigen', 'fremd', 'liefer', 'gemischt'].includes(classification.type) ||
      !isBoundedString(classification.reason, 500)
    ) throw new Error('invalid response');
    classifiedIds.add(classification.id);
    return {
      id: classification.id,
      type: classification.type,
      reason: classification.reason,
    };
  });
} catch {
  console.error('LLM_RESPONSE_INVALID_JSON');
  throw new Error('LLM_RESPONSE_INVALID_JSON');
}

const classMap = new Map(classified.map((classification) => [classification.id, classification]));
const enriched = positions.map(function(position, index) {
  const classification = classMap.get(classificationKey(index));
  return {
    id: position.id,
    short_text: position.short_text,
    unit: position.unit,
    type: classification.type,
    reason: classification.reason
  };
});

const summary = { eigen: 0, fremd: 0, liefer: 0, gemischt: 0, total: enriched.length };
for (const position of enriched) summary[position.type]++;

let semanticGroups = [];
let groupingStatus = 'needs_review';
let groupedTotal = 0;
try {
  const groups = parseIfString(rawGroups);
  if (!Array.isArray(groups) || groups.length < 1 || groups.length > positions.length) {
    throw new Error('invalid groups');
  }
  const knownIds = new Set(positions.map((_, index) => classificationKey(index)));
  const groupedIds = new Set();
  const groupIds = new Set();
  semanticGroups = groups.map((group) => {
    const positionIds = parseIfString(group.position_ids);
    const attributes = parseIfString(group.distinguishing_attributes);
    if (
      !isObject(group) ||
      !isBoundedString(group.id, 100) ||
      groupIds.has(group.id) ||
      !isBoundedString(group.label, 200) ||
      !['semantic', 'ambiguous'].includes(group.kind) ||
      !Array.isArray(positionIds) ||
      positionIds.length < 1 ||
      positionIds.length > positions.length ||
      !positionIds.every((id) =>
        isBoundedString(id, 100) && knownIds.has(id) && !groupedIds.has(id)
      ) ||
      !Array.isArray(attributes) ||
      attributes.length > 20 ||
      !attributes.every((attribute) => isBoundedString(attribute, 200)) ||
      typeof group.confidence !== 'number' ||
      !Number.isFinite(group.confidence) ||
      group.confidence < 0 ||
      group.confidence > 1 ||
      !isBoundedString(group.rationale, 1000)
    ) throw new Error('invalid groups');
    groupIds.add(group.id);
    positionIds.forEach((id) => groupedIds.add(id));

    const sourcePositions = positionIds.map((sourceId) => {
      const index = Number(sourceId.slice(4)) - 1;
      const position = positions[index];
      return {
        source_id: sourceId,
        id: position.id,
        short_text: position.short_text,
        category_path: Array.isArray(position.category_path) ? position.category_path : [],
        unit: position.unit,
        quantity: position.quantity,
      };
    });
    const totals = new Map();
    for (const sourcePosition of sourcePositions) {
      if (typeof sourcePosition.quantity !== 'number' || !Number.isFinite(sourcePosition.quantity)) continue;
      const unit = typeof sourcePosition.unit === 'string' && sourcePosition.unit.trim()
        ? sourcePosition.unit.trim()
        : null;
      const key = unit === null ? '__NO_UNIT__' : unit;
      const current = totals.get(key) || { unit, quantity: 0 };
      current.quantity += sourcePosition.quantity;
      totals.set(key, current);
    }
    return {
      id: group.id,
      label: group.label,
      kind: group.kind,
      position_ids: positionIds,
      distinguishing_attributes: attributes,
      confidence: group.confidence,
      rationale: group.rationale,
      source_positions: sourcePositions,
      quantity_totals: [...totals.values()],
    };
  });
  if (groupedIds.size !== positions.length) throw new Error('incomplete groups');
  groupingStatus = allPositions.length > 120 ? 'needs_review' : 'complete';
  groupedTotal = groupedIds.size;
} catch {
  semanticGroups = [];
}

const classifiedTotal = enriched.length;
const value_breakdown = {
  summary,
  positions: enriched,
  semantic_groups: semanticGroups,
  grouping_status: groupingStatus,
  grouped_total: groupedTotal,
  source_total: allPositions.length,
  classified_total: classifiedTotal,
  unclassified_total: allPositions.length - classifiedTotal,
  mode: allPositions.length > 120 ? 'chunked_needs_merge' : 'complete',
  classified_at: new Date().toISOString()
};

// Pass through previous node's json (requirements + summary)
return [{ json: { ...$json, value_breakdown } }];

const existing = $('parse-workload').first().json;
const breakdown = existing.value_breakdown;
const tender = $('load-tender').first().json;
const positions = Array.isArray(tender.gaeb_positions) ? tender.gaeb_positions : [];
if ($json.http_error === true || !breakdown || !positions.length) return [{ json: existing }];
const classificationKey = (index) => 'POS-' + String(index + 1).padStart(3, '0');
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isBoundedString = (value, maxLength) => typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const parseIfString = (value) => typeof value === 'string' ? JSON.parse(value) : value;
try {
  const content = $json.choices?.[0]?.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content.replace(/\x60\x60\x60json|\x60\x60\x60/g, '').trim()) : content;
  const groups = Array.isArray(parsed) ? parsed : parseIfString(parsed?.groups ?? parsed?.items);
  if (!Array.isArray(groups) || groups.length < 1 || groups.length > positions.length) throw new Error('invalid groups');
  const knownIds = new Set(positions.map((_, index) => classificationKey(index)));
  const groupedIds = new Set();
  const groupIds = new Set();
  const semanticGroups = groups.map(function(group) {
    const positionIds = parseIfString(group?.position_ids);
    const attributes = parseIfString(group?.distinguishing_attributes);
    if (!isObject(group) || !isBoundedString(group.id, 100) || groupIds.has(group.id) || !isBoundedString(group.label, 200) || !['semantic', 'ambiguous'].includes(group.kind) || !Array.isArray(positionIds) || positionIds.length < 1 || positionIds.length > positions.length || !positionIds.every((id) => isBoundedString(id, 100) && knownIds.has(id) && !groupedIds.has(id)) || !Array.isArray(attributes) || attributes.length > 20 || !attributes.every((attribute) => isBoundedString(attribute, 200)) || typeof group.confidence !== 'number' || !Number.isFinite(group.confidence) || group.confidence < 0 || group.confidence > 1 || !isBoundedString(group.rationale, 1000)) throw new Error('invalid groups');
    groupIds.add(group.id);
    positionIds.forEach((id) => groupedIds.add(id));
    const sourcePositions = positionIds.map(function(sourceId) {
      const position = positions[Number(sourceId.slice(4)) - 1];
      return { source_id: sourceId, id: position.id, short_text: position.short_text, category_path: Array.isArray(position.category_path) ? position.category_path : [], unit: position.unit, quantity: position.quantity };
    });
    const totals = new Map();
    for (const sourcePosition of sourcePositions) {
      if (typeof sourcePosition.quantity !== 'number' || !Number.isFinite(sourcePosition.quantity)) continue;
      const unit = typeof sourcePosition.unit === 'string' && sourcePosition.unit.trim() ? sourcePosition.unit.trim() : null;
      const key = unit === null ? '__NO_UNIT__' : unit;
      const current = totals.get(key) || { unit, quantity: 0 };
      current.quantity += sourcePosition.quantity;
      totals.set(key, current);
    }
    return { id: group.id, label: group.label, kind: group.kind, position_ids: positionIds, distinguishing_attributes: attributes, confidence: group.confidence, rationale: group.rationale, source_positions: sourcePositions, quantity_totals: [...totals.values()] };
  });
  if (groupedIds.size !== positions.length) throw new Error('incomplete groups');
  return [{ json: { ...existing, value_breakdown: { ...breakdown, semantic_groups: semanticGroups, grouping_status: 'complete', grouped_total: groupedIds.size, mode: 'chunked_complete' } } }];
} catch {
  return [{ json: existing }];
}

const summaryText = $json.choices[0].message.content || '';
const parsedRequirements = $('parse-requirements').first().json;
const requirements = parsedRequirements.requirements || [];
const requirements_coverage = parsedRequirements.requirements_coverage;
// Forward value_breakdown from parse-workload (IMP-04)
const value_breakdown = $('finalize-workload').first().json.value_breakdown || null;
return [{ json: { requirements, requirements_coverage, summary: summaryText.trim(), value_breakdown } }];
